cardCss:
.prelude-card {
    background: var(--card-bg, #fffdf8);
    border-radius: 16px;
    padding: 16px 20px;
    box-shadow: 0 1px 3px rgba(140,109,63,.10), 0 6px 16px rgba(140,109,63,.08);
    border: 1px solid var(--line, #ece3d2);
    border-left: 4px solid #b48a3f;
    min-height: 200px; display: flex; flex-direction: column;
}
.prelude-head { display: flex; align-items: flex-start; gap: 16px; margin-bottom: 8px; }
.prelude-diagram { flex-shrink: 0; padding-top: 2px; }
.prelude-mini-lines { display: flex; flex-direction: column; gap: 5px; }
.prelude-mini-line { width: 48px; height: 8px; border-radius: 4px; background: #1f2937; }
.prelude-mini-line.yin { background: transparent; position: relative; }
.prelude-mini-line.yin::before, .prelude-mini-line.yin::after { content: ""; position: absolute; top: 0; height: 8px; width: 19px; background: #1f2937; border-radius: 4px; }
.prelude-mini-line.yin::before { left: 0; }
.prelude-mini-line.yin::after { right: 0; }
.prelude-title-wrap { flex: 1; min-width: 0; }
.prelude-title { font-family: "Songti SC","STSong","SimSun",serif; font-weight: var(--card-font-weight, 800); color: #1f2937; font-size: calc(26px * var(--card-font-scale, 1)); letter-spacing: 2px; }
.prelude-pinyin { color: #6b7280; font-size: calc(13px * var(--card-font-scale, 1)); margin-top: 2px; }
.prelude-body { font-size: calc(15px * var(--card-font-scale, 1)); line-height: 1.7; color: #374151; }
.prelude-note { margin-top: 8px; font-size: calc(13px * var(--card-font-scale, 1)); line-height: 1.65; color: #6b7280; white-space: pre-line; border-top: 1px dashed var(--line, #ece3d2); padding-top: 8px; }
.prelude-tools { display: flex; gap: 6px; margin-top: 10px; }
.prelude-tools .action-btn { width: 38px; height: 38px; border: none; background: var(--action-btn-bg, #f3ede2); border-radius: 90px; cursor: pointer; display: flex; align-items: center; justify-content: center; color: #6b7280; transition: all .2s; }
.prelude-tools .action-btn svg, .action-btn i { width: 20px; height: 20px; }
.prelude-tools .action-btn:hover { transform: translateY(-2px); }
.prelude-tools .act-play:hover { background: #b48a3f; color: #fff; }
.prelude-tools .act-mark.is-active { color: var(--unknown, #f43f5e); }
.prelude-tools .act-fav.is-active { color: #eab308; }

.action-btn i { font-size: 18px; line-height: 1; }
.action-btn:hover i { transform: scale(1.1); }

.prelude-card { margin-bottom: 16px; }

.prelude-head { justify-content: space-between; }
.prelude-head-left { display: flex; gap: 16px; align-items: flex-start; min-width: 0; }
.prelude-tools { margin-top: 0; }

cardJs:
(function () {
    'use strict';
    function esc(s) {
        if (s == null) return '';
        return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
    }
    window.cardTemplate = {
        name: '易经入门卡',
        fields: [
            { key: 'title',   label: '主题', hideable: false },
            { key: 'pinyin',  label: '拼音' },
            { key: 'diagram', label: '卦象', hideable: false },
            { key: 'body',    label: '讲解', hideable: false },
            { key: 'note',    label: '注记' }
        ],
        render: function (cardHtml, cardData, api) {
            var data = api.getCardData ? api.getCardData() : cardData;
            var d = data.data || {};
            var hidden = (api.getHiddenFields && api.getHiddenFields()) || {};
            function isHidden(k) { return hidden.has && hidden.has(k); }
            function wrap(k, html) { return isHidden(k) ? '' : html; }
            var markActive = data.is_unknown === 1 ? 'is-active' : '';
            var favActive = data.is_favorite === 1 ? 'is-active' : '';
            var diagram = d.diagram || '';
            var diagHtml = '';
            if (diagram.length === 3) {
                var lines = '';
                for (var i = 0; i < 3; i++) {
                    var yin = diagram.charAt(i) === '0';
                    lines += '<div class="prelude-mini-line ' + (yin ? 'yin' : 'yang') + '"></div>';
                }
                diagHtml = '<div class="prelude-diagram"><div class="prelude-mini-lines">' + lines + '</div></div>';
            }
            var headInner = diagHtml + '<div class="prelude-title-wrap">' +
                wrap('title', '<div class="prelude-title">' + esc(d.title) + '</div>') +
                wrap('pinyin', '<div class="prelude-pinyin">' + esc(d.pinyin) + '</div>') +
                '</div>';
            return '<div class="prelude-card" data-card-id="' + data.id + '">' +
                '<div class="prelude-head">' +
                    '<div class="prelude-head-left">' + headInner + '</div>' +
                    '<div class="prelude-tools">' +
                        '<button class="action-btn act-play" data-action="play" data-tooltip="朗读"><i class="fa-solid fa-volume-high"></i></button>' +
                        '<button class="action-btn act-mark ' + markActive + '" data-action="mark" data-tooltip="标记"><i class="' + (data.is_unknown === 1 ? 'fa-solid' : 'fa-regular') + ' fa-star"></i></button>' +
                        '<button class="action-btn act-fav ' + favActive + '" data-action="favorite" data-tooltip="收藏"><i class="' + (data.is_favorite === 1 ? 'fa-solid' : 'fa-regular') + ' fa-bookmark"></i></button>' +
                    '</div>' +
                '</div>' +
                wrap('body', '<div class="prelude-body">' + esc(d.body) + '</div>') +
                wrap('note', (d.note ? '<div class="prelude-note">' + esc(d.note) + '</div>' : '')) +
            '</div>';
        },
        init: function (cardElement, cardData, api) {
            var playBtn = cardElement.querySelector('[data-action="play"]');
            if (playBtn) playBtn.addEventListener('click', function () {
                var d = cardData.data || {};
                api.playAudio(d.title || '');
                api.track('audio_play');
            });
            var markBtn = cardElement.querySelector('[data-action="mark"]');
            if (markBtn) markBtn.addEventListener('click', function () {
                api.toggleMark().then(function () { api.rerender(); });
                api.track('word_mark');
            });
            var favBtn = cardElement.querySelector('[data-action="favorite"]');
            if (favBtn) favBtn.addEventListener('click', function () {
                api.toggleFavorite().then(function () { api.rerender(); });
                api.track('favorite_toggle');
            });
        }
    };
})();
